() => {
  const w = window.open('http://127.0.0.1:3000', 'lineageTest', 'width=1600,height=1000');
  return w ? 'opened' : 'blocked';
}

() => {
  document.documentElement.style.zoom = '1';
  return 'zoom reset';
}

() => {
  const grids = Array.from(document.querySelectorAll('div.grid'));
  // lineage root is the dark container; find grids inside it
  const root = Array.from(document.querySelectorAll('div')).find(d => d.className && typeof d.className === 'string' && d.className.includes('bg-slate-900') && d.className.includes('rounded-3xl'));
  const info = {
    rootFound: !!root,
    gridCount: grids.length,
    gridsInRoot: root ? Array.from(root.querySelectorAll(':scope > div.grid')).length : 0
  };
  if (root) {
    const secs = Array.from(root.querySelectorAll(':scope > div.grid'));
    info.sections = secs.map((s, i) => {
      const r = s.getBoundingClientRect();
      return { i, top: Math.round(r.top + window.scrollY), height: Math.round(r.height), cls: s.className.slice(0, 60) };
    });
    const rr = root.getBoundingClientRect();
    info.rootTop = Math.round(rr.top + window.scrollY);
    info.rootHeight = Math.round(rr.height);
  }
  window.__lineageBaseline = info;
  return info;
}

() => {
  const grids = Array.from(document.querySelectorAll('div.grid'));
  const data = grids.map((g, i) => {
    const r = g.getBoundingClientRect();
    return {
      i,
      cls: g.className,
      top: Math.round(r.top + window.scrollY),
      height: Math.round(r.height),
      children: g.children.length,
      parentCls: (g.parentElement.className || '').slice(0, 80)
    };
  });
  window.__baseline = data;
  return data;
}

() => {
  const els = Array.from(document.querySelectorAll('div')).filter(d => d.children.length === 2 && d.textContent.includes('月度销售与利润趋势') && d.textContent.includes('AREA'));
  // find the card: the div with onMouseEnter handler -> has class containing 'rounded-xl' and cursor-pointer
  const cards = Array.from(document.querySelectorAll('div.cursor-pointer')).filter(d => d.textContent.includes('月度销售与利润趋势') && d.textContent.includes('AREA'));
  const card = cards[cards.length-1];
  if (card) {
    card.scrollIntoView({ block: 'center' });
    const r = card.getBoundingClientRect();
    return { found: true, top: r.top, height: r.height };
  }
  return { found: false, alt: els.length };
}

() => {
