async () => {
  const start = performance.now();
  let frames = 0;
  await new Promise(res => {
    const loop = () => {
      frames++;
      if (performance.now() - start < 1000) requestAnimationFrame(loop);
      else res(null);
    };
    requestAnimationFrame(loop);
  });
  return { fps: frames };
}

